"""
Pydantic schemas for Resume-to-Job Matching.
"""

from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field


class AIJobMatchExplanationPayload(BaseModel):
    """Schema to validate JSON explanation generated by Ollama for job match."""

    explanation: str = Field(..., description="Narrative analysis explaining compatibility")
    recommendations: list[str] = Field(default_factory=list, description="Actionable recommendations to improve match")


class JobMatchResponse(BaseModel):
    """Job match evaluation report response."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    user_id: int
    job_id: int
    resume_id: int | None = None
    match_score: float
    experience_match: float
    education_match: float
    matched_skills: list[str] = Field(default_factory=list)
    missing_skills: list[str] = Field(default_factory=list)
    explanation: str
    recommendations: list[str] = Field(default_factory=list)
    created_at: datetime
